<section class="fmstr-cmp-jvt-demos" aria-labelledby="fmstr-cmp-jvt-demos-heading">
  <div class="fmstr-cmp-jvt-demos__container">

    <header class="fmstr-cmp-jvt-demos__header">
      <span class="fmstr-cmp-jvt-demos__eyebrow">Inside Formester</span>
      <h2 id="fmstr-cmp-jvt-demos-heading" class="fmstr-cmp-jvt-demos__heading">What does Formester look like in practice?</h2>
      <p class="fmstr-cmp-jvt-demos__sub">Three Formester workflows, if neither of the two above fits.</p>
    </header>

    <input type="radio" name="fmstr-cmp-jvt-demos-tab" id="fmstr-cmp-jvt-demos-t1" class="fmstr-cmp-jvt-demos__radio fmstr-cmp-jvt-demos__t1" checked>
    <input type="radio" name="fmstr-cmp-jvt-demos-tab" id="fmstr-cmp-jvt-demos-t2" class="fmstr-cmp-jvt-demos__radio fmstr-cmp-jvt-demos__t2">
    <input type="radio" name="fmstr-cmp-jvt-demos-tab" id="fmstr-cmp-jvt-demos-t3" class="fmstr-cmp-jvt-demos__radio fmstr-cmp-jvt-demos__t3">

    <div class="fmstr-cmp-jvt-demos__tabbar" role="tablist" aria-label="Formester workflow demos">
      <label for="fmstr-cmp-jvt-demos-t1" class="fmstr-cmp-jvt-demos__tab fmstr-cmp-jvt-demos__tab--1"><svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 1.5l2 6.9 6.9 2-6.9 2-2 6.9-2-6.9-6.9-2 6.9-2z"/></svg>
