    <div class="fmstr-cmp-jvt-demos__panels">
      <div class="fmstr-cmp-jvt-demos__panel fmstr-cmp-jvt-demos__panel--1">
        <div class="fmstr-cmp-jvt-demos__frame">
        <div class="fmstr-cmp-jvt-demos__card">
          <div class="fmstr-cmp-jvt-demos__text">
            <h3 class="fmstr-cmp-jvt-demos__title">Create a form from one prompt</h3>
            <p class="fmstr-cmp-jvt-demos__body">Describe what you need and the AI writes the fields, pages, and design. Edit anything after.</p>
          </div>
          <img class="fmstr-cmp-jvt-demos__media" src="https://formester-strapi.s3.ap-south-1.amazonaws.com/formester_ai_survey_generation_4292f1cbcb.gif" alt="Formester AI generator building a full form from a one-sentence text prompt" width="900" height="534" loading="lazy" />
